import{_ as o,C as r,o as s,c as i,j as t,a as n,E as d,a6 as h}from"./chunks/framework.CCKCzdWs.js";const g=JSON.parse('{"title":"Run video","description":"Play the videos Playwright recorded for a finished run, one test after another, beside a checklist that ticks as each test ends.","frontmatter":{"title":"Run video","description":"Play the videos Playwright recorded for a finished run, one test after another, beside a checklist that ticks as each test ends.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/run-video.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/run-video.html"}],["meta",{"property":"og:title","content":"Run video | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Play the videos Playwright recorded for a finished run, one test after another, beside a checklist that ticks as each test ends."}]]},"headers":[],"relativePath":"features/run-video.md","filePath":"features/run-video.md","lastUpdated":1794504053000}'),l={name:"features/run-video.md"};function c(p,e,f,u,v,m){const a=r("Needs");return s(),i("div",null,[e[0]||(e[0]=t("h1",{id:"run-video",tabindex:"-1"},[n("Run video "),t("a",{class:"header-anchor",href:"#run-video","aria-label":'Permalink to "Run video"'},"​")],-1)),d(a,{reporter:""}),e[1]||(e[1]=h('<p>A finished run has a <strong>Video</strong> tab, labelled with the number of tests that have a video (<strong>Video (12)</strong>). It plays the videos Playwright recorded for the run, one test after another, beside a checklist of the tests. A test is ticked as its video passes the end of the test, so you can follow a worker&#39;s run as it happened. The bar under the video has one block for each test, colored by its result. Click a test or the bar to jump there.</p><h2 id="group-by-worker-or-file" tabindex="-1">Group by Worker or File <a class="header-anchor" href="#group-by-worker-or-file" aria-label="Permalink to &quot;Group by Worker or File&quot;">​</a></h2><ul><li><strong>Worker</strong> plays one worker&#39;s tests in the order they ran. Pick the worker above the video.</li><li><strong>File</strong> plays every test in the order its file declares it, each marked with the worker it ran on. The tests ran in parallel, so this order is not the order they ran in.</li></ul><p>Only the final attempt of a test is listed. A test that has no video stays on the checklist and takes a small block on the bar. It is ticked as the reel moves on. The tab is off while the run is live.</p><h2 id="open-a-video-review-from-evidence" tabindex="-1">Open a video review from Evidence <a class="header-anchor" href="#open-a-video-review-from-evidence" aria-label="Permalink to &quot;Open a video review from Evidence&quot;">​</a></h2><p>On a finished execution that has a video, the Evidence header has an <strong>Open video review</strong> button, beside <strong>Open trace</strong>. It opens the video with the same bar and checklist as the Video tab, in a window that fills a narrow screen. The window&#39;s switch picks what plays, and it starts on <strong>This test</strong>:</p><ul><li><strong>This test</strong> plays only that test, from the start of its video to its end, and stops. The file&#39;s other tests stay on the checklist, dimmed, and are not played.</li><li><strong>Whole file</strong> plays the file&#39;s final attempts in declared order, each marked with its worker, and starts on this test.</li><li><strong>Its worker</strong> plays the tests of this test&#39;s worker, in the order they ran, and starts on this test. A sharded run keeps each shard&#39;s workers apart.</li></ul><p>In these two modes only the tests that play are ticked, and <strong>Play</strong> after the end starts again from this test. The opened test is marked <strong>This test</strong> in every mode. Closing the window stops the video.</p><p>Only final attempts that ran are in the file and worker reels. On an earlier attempt or a skipped test, This test plays its own video and the other two modes are off, with the reason shown under the switch. A run lists at most 2,000 tests with a video, so a test past that limit also keeps only This test.</p><h2 id="when-there-are-no-videos" tabindex="-1">When there are no videos <a class="header-anchor" href="#when-there-are-no-videos" aria-label="Permalink to &quot;When there are no videos&quot;">​</a></h2><p>Most suites record video only for failing tests (<code>video: &#39;retain-on-failure&#39;</code>), so a run where nothing failed often has none. The tab is then disabled, with the tooltip &quot;no videos in this run&quot;. Set <code>video: &#39;on&#39;</code> in Playwright&#39;s <code>use</code> options to record every test. Videos can be large, so read <a href="/operate/storage.html#storage-management">storage cleanup</a> first.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./evidence.html">Failure evidence</a>: one failing execution, with its trace, screenshots and video</li><li><a href="/operate/storage.html#storage-management">Storage</a>: how long videos are kept</li></ul>',13))])}const k=o(l,[["render",c]]);export{g as __pageData,k as default};
